  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 3vw, 1.75rem);
  margin-bottom: var(--spacing-md);
  color: var(--color-accent);
  font-weight: 300;
}

.index-hero-description {
  font-size: 1.1rem;
  max-width: 600px;
  margin: 0 auto var(--spacing-lg);
  line-height: 1.7;
}

.index-hero-cta {
  display: inline-flex;
  background-color: var(--color-accent-on-dark);
  color: var(--color-primary-dark);
  padding: var(--spacing-sm) var(--spacing-lg);
  border-radius: 4px;
  font-weight: 600;
  font-size: 1rem;
  text-decoration: none;
  transition: background-color 0.2s ease, transform 0.1s ease;
  min-height: 44px;
  align-items: center;
  justify-content: center;
}

.index-hero-cta:hover {
  background-color: var(--color-accent);
  transform: translateY(-2px);
}

.index-hero-cta:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.index-featured {
  padding: var(--spacing-xl) var(--spacing-md);
}

.index-featured h2 {
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

.index-featured-price {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  color: var(--color-accent-dark);
  font-weight: 600;
  margin-top: var(--spacing-md);
  margin-bottom: 0;
}

.index-menu {
  padding: var(--spacing-xl) var(--spacing-md);
  background-color: #fafaf5;
}

.index-menu h2 {
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

.index-menu-category {
  margin-bottom: var(--spacing-xl);
}

.index-menu-category h3 {
  border-bottom: 2px solid var(--color-accent);
  padding-bottom: var(--spacing-md);
  margin-bottom: var(--spacing-lg);
}

.index-menu-item {
  margin-bottom: var(--spacing-lg);
  padding-bottom: var(--spacing-lg);
  border-bottom: 1px solid var(--color-border);
}

.index-menu-item:last-child {
  border-bottom: none;
  margin-bottom: 0;
  padding-bottom: 0;
}

.index-menu-item-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: var(--spacing-md);
  margin-bottom: var(--spacing-sm);
}

.index-menu-item h4 {
  font-size: 1.15rem;
  margin-bottom: 0;
  color: var(--color-primary);
  flex: 1;
}

.index-menu-price {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  color: var(--color-accent-dark);
  font-weight: 600;
  white-space: nowrap;
  flex-shrink: 0;
}

.index-menu-item p {
  color: var(--color-text-light);
  margin-bottom: 0;
  font-size: 0.95rem;
}

.index-reservations {
  padding: var(--spacing-xl) var(--spacing-md);
}

.index-reservations h2 {
  text-align: center;
  margin-bottom: var(--spacing-md);
}

.index-reservations > .container > p {
  text-align: center;
  max-width: 600px;
  margin: 0 auto var(--spacing-xl);
  color: var(--color-text-light);
}

.index-reservation-form {
  max-width: 600px;
  margin: 0 auto;
  background-color: white;
  padding: var(--spacing-lg);
  border: 1px solid var(--color-border);
  border-radius: 6px;
}

@media (max-width: 600px) {
  .index-hero {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .index-hero h1 {
    margin-bottom: var(--spacing-sm);
  }

  .index-hero-tagline {
    margin-bottom: var(--spacing-sm);
  }

  .index-hero-description {
    font-size: 1rem;
    margin-bottom: var(--spacing-lg);
  }

  .index-featured {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .index-featured h2 {
    margin-bottom: var(--spacing-lg);
  }

  .index-menu {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .index-menu h2 {
    margin-bottom: var(--spacing-lg);
  }

  .index-menu-category {
    margin-bottom: var(--spacing-lg);
  }

  .index-menu-item-header {
    flex-direction: column;
    gap: var(--spacing-sm);
  }

  .index-menu-price {
    font-size: 1.1rem;
  }

  .index-reservations {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .index-reservation-form {
    padding: var(--spacing-md);
  }
}

@media (min-width: 601px) {
  .index-hero {
    padding: var(--spacing-xl) var(--spacing-lg);
  }

  .index-featured {
    padding: var(--spacing-xl) var(--spacing-lg);
  }

  .index-menu {
    padding: var(--spacing-xl) var(--spacing-lg);
  }

  .index-reservations {
    padding: var(--spacing-xl) var(--spacing-lg);
  }

  .index-menu-item-header {
    align-items: center;
  }
}
